    private static void drawBackground(Canvas c, Rect r, int bgColor, int color) {
        Paint paint = new Paint();
        paint.setColor(bgColor);
        paint.setAntiAlias(true);
        c.drawRect(r, paint);
        int topColor = Color.argb(GRADIENT_TOP_ALPHA, Color.red(color), Color.green(color), Color.blue(color));
        int[] gradientColors = {topColor, color};
        GradientDrawable shine = new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM, gradientColors);
        int stop = ((int) (r.height() * GRADIENT_STOP)) + r.top;
        shine.setBounds(r.left, r.top, r.right, stop);
        shine.draw(c);
        Rect shadowRect = new Rect(r.left, stop, r.right, r.bottom);
        Paint shadowPaint = new Paint();
        shadowPaint.setColor(color);
        c.drawRect(shadowRect, shadowPaint);
    }

    private BitmapDrawable generateBackgroundDrawable(Rect r, int bgColor, int color) {
        return generateBackgroundDrawable(r, bgColor, color, false);
    }

    private BitmapDrawable generateBackgroundDrawable(Rect r, int bgColor, int color, boolean addFocusRing) {
        try {
            Bitmap bitmap = Bitmap.createBitmap(r.width(), r.height(), Bitmap.Config.ARGB_8888);
            Canvas canvas = new Canvas(bitmap);
            drawBackground(canvas, r, bgColor, color);
            if (addFocusRing) {
                drawFocusRing(canvas, r);
            }
            return new BitmapDrawable(bitmap);
        } catch (Throwable th) {
            return null;
        }
    }

