    public boolean dispatchTouchEvent(MotionEvent e) {
        int action = e.getAction();
        if (Log.isLoggable("innerActive", 2)) {
            Log.v("innerActive", "dispatchTouchEvent: action=" + action + " x=" + e.getX() + " y=" + e.getY());
        }
        if (action == 0) {
            setPressed(true);
        } else if (action == 2) {
            float x = e.getX();
            float y = e.getY();
            int left = getLeft();
            int top = getTop();
            int right = getRight();
            int bottom = getBottom();
            if (x < left || x > right || y < top || y > bottom) {
                setPressed(false);
            } else {
                setPressed(true);
            }
        } else if (action == 1) {
            if (isPressed()) {
