    private void click() {
        if (this.ad != null && isPressed()) {
            setPressed(false);
            if (!this.clickInProgress) {
                this.clickInProgress = true;
                if (this.bannerView != null) {
                    AnimationSet animSet = new AnimationSet(true);
                    float pivotX = this.bannerView.getWidth() / 2.0f;
                    float pivotY = this.bannerView.getHeight() / 2.0f;
                    ScaleAnimation growAnim = new ScaleAnimation(PULSE_INITIAL_SCALE, PULSE_GROWN_SCALE, PULSE_INITIAL_SCALE, PULSE_GROWN_SCALE, pivotX, pivotY);
                    growAnim.setDuration(200L);
                    animSet.addAnimation(growAnim);
                    ScaleAnimation shrinkAnim = new ScaleAnimation(PULSE_GROWN_SCALE, PULSE_SHRUNKEN_SCALE, PULSE_GROWN_SCALE, PULSE_SHRUNKEN_SCALE, pivotX, pivotY);
                    shrinkAnim.setDuration(299L);
                    shrinkAnim.setStartOffset(200L);
                    shrinkAnim.setAnimationListener(this);
                    animSet.addAnimation(shrinkAnim);
                    postDelayed(new Thread() { // from class: com.innerActive.ads.InnerActiveAdContainer.3
                        @Override // java.lang.Thread, java.lang.Runnable
                        public void run() {
                            InnerActiveAdContainer.this.ad.clicked();
                        }
                    }, 500L);
                    this.bannerView.startAnimation(animSet);
                    return;
                }
                this.ad.clicked();
            }
        }
    }

