package com.zingmagic.backgammonlite;

    private class AntiANRThread extends Thread {
        private ConcurrentLinkedQueue<BackgammonView.AppGameEvent> iANREventQueue = new ConcurrentLinkedQueue<>();
        private boolean iAllowedToRun = true;
        private AnimationThread iParent;

        public AntiANRThread(AnimationThread aParent) {
            this.iParent = aParent;
        }

        public void stopRunning() {
            this.iAllowedToRun = false;
        }

        @Override // java.lang.Thread, java.lang.Runnable
        public void run() {
            while (this.iAllowedToRun) {
                BackgammonView.AppGameEvent event = this.iANREventQueue.poll();
                if (event == null) {
                    try {
                        Thread.sleep(10L);
                    } catch (InterruptedException e) {
                    }
                } else {
                    this.iParent.doAddEvent(event);
                }
            }
        }

        public void addEvent(BackgammonView.AppGameEvent aEvent) {
            this.iANREventQueue.add(aEvent);
        }
    }

